import{_ as e,o as r,c as s,a2 as o}from"./chunks/framework.D8Tso2Ul.js";const m=JSON.parse('{"title":"Primeros pasos","description":"","frontmatter":{},"headers":[],"relativePath":"guia-inicio/primeros-pasos.md","filePath":"guia-inicio/primeros-pasos.md"}'),i={name:"guia-inicio/primeros-pasos.md"};function n(t,a,l,d,c,p){return r(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h1><p>Una vez instalada la plataforma, este es el recorrido típico para poner una obra en marcha y empezar a operar.</p><h2 id="_1-iniciar-sesion" tabindex="-1">1. Iniciar sesión <a class="header-anchor" href="#_1-iniciar-sesion" aria-label="Permalink to &quot;1. Iniciar sesión&quot;">​</a></h2><p>Ingresa con las credenciales del administrador (creadas durante el <a href="/manual/guia-inicio/onboarding.html">onboarding del tenant</a>). La sesión usa JWT; ver <a href="/manual/api/autenticacion.html">Autenticación</a>.</p><h2 id="_2-configurar-la-empresa-tenant" tabindex="-1">2. Configurar la empresa (tenant) <a class="header-anchor" href="#_2-configurar-la-empresa-tenant" aria-label="Permalink to &quot;2. Configurar la empresa (tenant)&quot;">​</a></h2><p>Como admin, revisa la configuración de tu empresa:</p><ul><li><strong>Módulos activos</strong> según tu plan.</li><li><strong>Reglas SST</strong>: qué fases del DS 44 aplican a tus obras.</li><li><strong>Personalización</strong>: logo, colores, preferencias regionales.</li></ul><p>Ver <a href="/manual/modulos/tenants.html">Tenants</a>.</p><h2 id="_3-crear-una-obra" tabindex="-1">3. Crear una obra <a class="header-anchor" href="#_3-crear-una-obra" aria-label="Permalink to &quot;3. Crear una obra&quot;">​</a></h2><p>Crea tu primera obra. Al hacerlo, la plataforma <strong>precrea automáticamente</strong> los documentos obligatorios de cada fase según las reglas del tenant.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nueva obra → fasesConfig precargado → documentos obligatorios listos</span></span></code></pre></div><p>Ver <a href="/manual/modulos/obras.html">Obras</a>.</p><h2 id="_4-registrar-personas" tabindex="-1">4. Registrar personas <a class="header-anchor" href="#_4-registrar-personas" aria-label="Permalink to &quot;4. Registrar personas&quot;">​</a></h2><p>Da de alta a las personas de la obra (prevencionista, supervisores, trabajadores). Define para cada una:</p><ul><li>Su <strong>rol</strong> (determina permisos).</li><li>Si <strong>tiene acceso web</strong> o solo firma en terreno.</li><li>Las <strong>obras</strong> a las que está asignada.</li></ul><p>Ver <a href="/manual/modulos/personas.html">Personas</a>.</p><h2 id="_5-cargar-y-firmar-documentos" tabindex="-1">5. Cargar y firmar documentos <a class="header-anchor" href="#_5-cargar-y-firmar-documentos" aria-label="Permalink to &quot;5. Cargar y firmar documentos&quot;">​</a></h2><ul><li>Sube los archivos a los documentos obligatorios de la fase actual.</li><li>Asigna documentos diarios a las personas que correspondan.</li><li>Las personas reciben notificación y firman con su PIN.</li></ul><p>Ver <a href="/manual/modulos/documentos.html">Documentos</a> y <a href="/manual/modulos/firmas.html">Firmas</a>.</p><h2 id="_6-programar-actividades" tabindex="-1">6. Programar actividades <a class="header-anchor" href="#_6-programar-actividades" aria-label="Permalink to &quot;6. Programar actividades&quot;">​</a></h2><p>Programa charlas y capacitaciones. Registra asistencia y recoge las firmas de los asistentes y del relator.</p><p>Ver <a href="/manual/modulos/actividades.html">Actividades</a>.</p><h2 id="_7-monitorear-desde-el-dashboard" tabindex="-1">7. Monitorear desde el Dashboard <a class="header-anchor" href="#_7-monitorear-desde-el-dashboard" aria-label="Permalink to &quot;7. Monitorear desde el Dashboard&quot;">​</a></h2><p>Revisa los KPIs de seguridad, el cumplimiento por fase y los incidentes recientes desde el <a href="/manual/modulos/dashboard.html">Dashboard</a>.</p><h2 id="flujo-resumido" tabindex="-1">Flujo resumido <a class="header-anchor" href="#flujo-resumido" aria-label="Permalink to &quot;Flujo resumido&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Login → Configurar tenant → Crear obra → Registrar personas</span></span>
<span class="line"><span>   → Cargar/firmar documentos → Programar actividades → Monitorear</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Avance de fase</p><p>Cuando la fase actual tenga todos sus documentos obligatorios firmados, el jefe de obra podrá avanzar a la siguiente fase. La plataforma verifica el cumplimiento antes de permitirlo. Ver <a href="/manual/ds44/fases-obra.html">Fases de obra</a>.</p></div>`,27)])])}const h=e(i,[["render",n]]);export{m as __pageData,h as default};
